if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nombre=trim($_POST['nombre']??'');$carrera=(int)($_POST['carrera_id']??0);$mod=(int)($_POST['modulo_num']??0);$ciclo=(int)($_POST['ciclo_num']??0);if($nombre!==''&&$carrera>0&&$mod>=1&&$mod<=3&&$ciclo>=1&&$ciclo<=2){$s=$pdo->prepare('INSERT INTO unidades_didacticas(carrera_id,modulo_num,ciclo_num,nombre) VALUES(?,?,?,?)');$s->execute([$carrera,$mod,$ciclo,$nombre]);audit($pdo,(int)current_user()['id'],'crear_unidad_didactica',$nombre);flash('success','Unidad didáctica registrada.');}else flash('error','Completa todos los campos correctamente.');redirect('academico.php');}
$careers=$pdo->query('SELECT * FROM carreras ORDER BY id')->fetchAll();$units=$pdo->query('SELECT u.*,c.nombre carrera FROM unidades_didacticas u JOIN carreras c ON c.id=u.carrera_id ORDER BY c.id,u.modulo_num,u.ciclo_num,u.nombre')->fetchAll();
